=SUM(
  SELECT(
    Loans[Total Interest Received],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

=SUM(
  SELECT(
    Loans[Total Interest Received],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

=SUM(
  SELECT(
    Loans[Expected Daily Interest Amount],
    [Ref Borrowers] = [_THISROW].[Row ID]
  )
)

=SUM(
  SELECT(
    Loans[30D Principal Days],
    [Ref Borrowers] = [_THISROW].[Row ID]
  )
)

=SUM(
  SELECT(
    Repayments[30D Principal Reduction Days],
    [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID]
  )
)

=COUNT(
  SELECT(
    Loans[Row ID],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

=MAX(
  SELECT(
    Loans[Loan Age Days],
    AND([Ref Borrowers] = [_THISROW].[Row ID], [Loan Status] = "ยังไม่ปิดยอด")
  )
)

=SUM(
  SELECT(
    Charges[Amount Remaining],
    AND(
      [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
      [Charge Date] < TODAY(),
      [Payment Status] <> "ชำระแล้ว"
    )
  )
)

=COUNT(
  SELECT(
    Charges[Row ID],
    AND(
      [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
      [Charge Date] < TODAY(),
      [Payment Status] <> "ชำระแล้ว"
    )
  )
)

=FLOOR(
  TOTALHOURS(
    TODAY()
      - MIN(
        SELECT(
          Charges[Charge Date],
          AND(
            [Ref Loans].[Ref Borrowers] = [_THISROW].[Row ID],
            [Charge Date] < TODAY()
          )
        )
      )
  )
    / 24
) >= 3
